using Contoso.Text;

namespace Contoso.Text.Tests;

[TestClass]
public sealed class StringFormatterTests
{
    private readonly StringFormatter _formatter = new();

    [TestMethod]
    [DataRow("5551234567")]
    [DataRow("8005551234")]
    public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens(string digits)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.StartsWith($"({digits[..3]})", result);
    }

    [TestMethod]
    [DataRow("5551234567", "4567")]
    [DataRow("8005551234", "1234")]
    public void FormatPhoneNumber_ValidDigits_EndsWithLastFour(string digits, string lastFour)
    {
        var result = _formatter.FormatPhoneNumber(digits);

        Assert.EndsWith(lastFour, result);
    }

    [TestMethod]
    public void FormatPhoneNumber_ValidDigits_MatchesFullFormat()
    {
        var result = _formatter.FormatPhoneNumber("5551234567");

        Assert.AreEqual("(555) 123-4567", result);
        Assert.MatchesRegex(@"\(\d{3}\) \d{3}-\d{4}", result);
    }

    [TestMethod]
    public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.FormatPhoneNumber(null!));
        Assert.AreEqual("digits", ex.ParamName);
    }

    [TestMethod]
    [DataRow("123")]
    [DataRow("12345678901")]
    public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.FormatPhoneNumber(digits));
    }

    [TestMethod]
    [DataRow("Alice", "Mr.", "Dear Mr. Alice,")]
    [DataRow("Bob", "Dr.", "Dear Dr. Bob,")]
    public void BuildGreeting_WithTitle_StartsWithDearAndTitle(string name, string title, string expected)
    {
        var result = _formatter.BuildGreeting(name, title);

        Assert.StartsWith($"Dear {title}", result);
        Assert.EndsWith(",", result);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void BuildGreeting_DefaultTitle_UsesMr()
    {
        var result = _formatter.BuildGreeting("Smith");

        Assert.StartsWith("Dear Mr.", result);
        Assert.Contains("Smith", result);
        Assert.EndsWith(",", result);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void BuildGreeting_NullOrWhitespace_Throws(string? name)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _formatter.BuildGreeting(name!));
    }

    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("  My Blog Post!  ", "my-blog-post")]
    [DataRow("C# is great", "c-is-great")]
    public void GenerateSlug_ValidTitle_ReturnsLowercaseHyphenated(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
        Assert.MatchesRegex(@"^[a-z0-9]+(-[a-z0-9]+)*$", result);
    }

    [TestMethod]
    public void GenerateSlug_MultipleSpecialChars_DoesNotStartOrEndWithHyphen()
    {
        var result = _formatter.GenerateSlug("---Hello---World---");

        Assert.StartsWith("h", result);
        Assert.EndsWith("d", result);
    }

    [TestMethod]
    [DataRow(99.99, "$", "$99.99")]
    [DataRow(0.5, "€", "€0.50")]
    [DataRow(1000, "£", "£1000.00")]
    public void FormatCurrency_WithSymbol_StartsWithSymbolAndEndsWith2Decimals(
        double amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency((decimal)amount, symbol);

        Assert.StartsWith(symbol, result);
        Assert.MatchesRegex(@"\.\d{2}$", result);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
    {
        var result = _formatter.FormatCurrency(42.10m);

        Assert.StartsWith("$", result);
        Assert.EndsWith("42.10", result);
    }
}

